// Original dynamic parity-constraint problem. A query reconstructs its component
// in the independent oracle; the generated reference uses offline rollback.
export function dynamicParityComponentCostOracle([weights,edges,operations]) {
 const n=weights.length,adjacency=Array.from({length:n},()=>[]),active=Array(edges.length/3).fill(false),out=[];
 for(let id=0;id<active.length;id++){
  const u=edges[id*3],v=edges[id*3+1];adjacency[u].push(id);if(u!==v)adjacency[v].push(id);
 }
 for(let i=0;i<operations.length;i+=2){
  const kind=operations[i],x=operations[i+1];
  if(kind<2){active[x]=kind===0;continue;}
  const color=new Int8Array(n).fill(-1),queue=[x],cost=[0,0];let valid=true;color[x]=0;
  for(let head=0;head<queue.length;head++){
   const u=queue[head];cost[color[u]]+=weights[u];
   for(const id of adjacency[u])if(active[id]){
    const a=edges[id*3],b=edges[id*3+1],v=a===u?b:a,expected=color[u]^edges[id*3+2];
    if(color[v]===-1){color[v]=expected;queue.push(v);}else if(color[v]!==expected)valid=false;
   }
  }
  out.push(valid?Math.min(...cost):-1);
 }
 return out;
}

